class Matrix:

	def __init__(self, n):
		self.n = n
		self.a = [[0] * n for _ in range(n)]

	def __mul__(self, b):
		res = Matrix(self.n)
		for i in range(self.n):
			for j in range(self.n):
				for k in range(self.n):
					res.a[i][j] += self.a[i][k] * b.a[k][j] % mod
					res.a[i][j] %= mod
		return res

	def __pow__(self, e):
		res = Matrix(self.n)
		for i in range(self.n):
			res.a[i][i] = 1
		tmp = self
		while e:
			if e & 1:
				res = res * tmp
			e >>= 1
			tmp = tmp * tmp
		return res
